using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(nameof(Chat_RespondsRelevantly));

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        // Verify the response contains relevant content
        Assert.IsNotNull(response);
        Assert.IsFalse(string.IsNullOrWhiteSpace(response.Text));
    }

    [TestMethod]
    public async Task Chat_MaintainsCoherence()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(nameof(Chat_MaintainsCoherence));

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about climate change in two sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(response.Message);

        // Follow-up to test multi-turn coherence
        messages.Add(new ChatMessage(ChatRole.User, "Can you elaborate on the second point?"));

        var followUp = await chatClient.GetResponseAsync(messages);

        messages.Add(followUp.Message);

        await scenario.EvaluateAsync(messages);

        Assert.IsNotNull(followUp);
        Assert.IsFalse(string.IsNullOrWhiteSpace(followUp.Text));
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var reportDir = Path.Combine(
            AppContext.BaseDirectory,
            "evaluation-report");

        return DiskBasedReportingConfiguration.Create(
            storageRootDir: reportDir,
            evaluators: evaluators,
            chatConfiguration: GetEvaluationChatConfiguration());
    }

    private static ChatConfiguration GetEvaluationChatConfiguration()
    {
        // Uses the same chat client from the app host for LLM-as-judge evaluation.
        // In production, you may want a separate evaluator model endpoint.
        return new ChatConfiguration(
            () => _appHost.Services.GetRequiredService<IChatClient>());
    }
}

